  font: inherit;
}
.terminal-markdown :not(pre) > code {
  padding: 0;
  border: 0;
  background: transparent;
  color: var(--terminal-cyan);
}
.terminal-markdown pre,
.terminal-code-block,
.terminal-code-block pre {
  box-sizing: border-box;
  max-width: 100%;
  margin: 0 0 1.5em;
  padding: 0;
  overflow-x: auto;
  border: 0;
